#!/usr/bin/env node
/**
 * Level generator for "Find Panda" puzzle game.
 * Generates levels with guaranteed unique solutions following all rules:
 * 1. Each bamboo pairs with exactly one adjacent panda (orthogonal)
 * 2. Each panda pairs with exactly one bamboo
 * 3. Pandas can't touch each other (including diagonals)
 * 4. Row/column counts match
 */

function getOrthogonal(r, c, size) {
    const adj = [];
    if (r > 0) adj.push([r - 1, c]);
    if (r < size - 1) adj.push([r + 1, c]);
    if (c > 0) adj.push([r, c - 1]);
    if (c < size - 1) adj.push([r, c + 1]);
    return adj;
}

function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
}

// Check if a panda can be placed at (r,c) without touching existing pandas
function canPlacePanda(r, c, pandas, size) {
    for (const [pr, pc] of pandas) {
        if (Math.abs(pr - r) <= 1 && Math.abs(pc - c) <= 1) return false;
    }
    return true;
}

// Step 1: Place N pandas with no adjacency (including diagonals)
function placePandas(size, count) {
    const positions = [];
    for (let r = 0; r < size; r++)
        for (let c = 0; c < size; c++)
            positions.push([r, c]);

    const pandas = [];

    function backtrack(startIdx) {
        if (pandas.length === count) return true;

        // Shuffle remaining positions for randomness
        const remaining = positions.slice(startIdx);
        shuffle(remaining);

        for (const [r, c] of remaining) {
            if (canPlacePanda(r, c, pandas, size)) {
                pandas.push([r, c]);
                if (backtrack(0)) return true; // restart search from 0 for randomness
                pandas.pop();
            }
        }
        return false;
    }

    // Simpler random approach: try placing one by one
    for (let attempt = 0; attempt < 200; attempt++) {
        pandas.length = 0;
        const shuffled = shuffle([...positions]);

        for (const [r, c] of shuffled) {
            if (pandas.length >= count) break;
            if (canPlacePanda(r, c, pandas, size)) {
                pandas.push([r, c]);
            }
        }

        if (pandas.length === count) return pandas;
    }

    return null;
}

// Step 2: Assign a bamboo to each panda
// Extra constraint: a bamboo cell must not be orthogonally adjacent to any OTHER panda
// (it's fine being adjacent to its own paired panda — that's required)
function assignBamboos(pandas, size) {
    const pandaSet = new Set(pandas.map(([r, c]) => `${r},${c}`));
    const bambooSet = new Set();
    const bamboos = [];

    for (let pi = 0; pi < pandas.length; pi++) {
        const [pr, pc] = pandas[pi];
        const adj = shuffle(getOrthogonal(pr, pc, size));
        let placed = false;
        for (const [ar, ac] of adj) {
            const key = `${ar},${ac}`;
            if (pandaSet.has(key) || bambooSet.has(key)) continue;

            // Check this bamboo position is not adjacent to any OTHER panda
            const otherAdj = getOrthogonal(ar, ac, size);
            const adjPandaCount = otherAdj.filter(([r, c]) => pandaSet.has(`${r},${c}`)).length;
            // It should only be adjacent to exactly 1 panda (its own)
            if (adjPandaCount !== 1) continue;

            bamboos.push([ar, ac]);
            bambooSet.add(key);
            placed = true;
            break;
        }
        if (!placed) return null;
    }

    return bamboos;
}

// Step 3: Compute row/col counts
function computeCounts(pandas, size) {
    const rowCounts = Array(size).fill(0);
    const colCounts = Array(size).fill(0);
    for (const [r, c] of pandas) {
        rowCounts[r]++;
        colCounts[c]++;
    }
    return { rowCounts, colCounts };
}

// Step 4: Verify unique solution via backtracking
function verifyUniqueSolution(bamboos, rowCounts, colCounts, size) {
    const bambooSet = new Set(bamboos.map(([r, c]) => `${r},${c}`));

    // For each bamboo, find all candidate panda positions (orthogonal, not a bamboo)
    const candidates = bamboos.map(([br, bc]) => {
        return getOrthogonal(br, bc, size).filter(([r, c]) => !bambooSet.has(`${r},${c}`));
    });

    let solutionCount = 0;
    const placed = [];          // [r, c] of placed pandas
    const usedCells = new Set();

    function canPlace(r, c) {
        // Check 8-directional non-adjacency with all placed pandas
        for (const [pr, pc] of placed) {
            if (Math.abs(pr - r) <= 1 && Math.abs(pc - c) <= 1) return false;
        }
        return true;
    }

    function backtrack(idx) {
        if (solutionCount > 1) return; // early exit
        if (idx === bamboos.length) {
            // Verify row/col counts
            const rc = Array(size).fill(0);
            const cc = Array(size).fill(0);
            for (const [r, c] of placed) { rc[r]++; cc[c]++; }
            for (let i = 0; i < size; i++) {
                if (rc[i] !== rowCounts[i] || cc[i] !== colCounts[i]) return;
            }
            solutionCount++;
            return;
        }

        for (const [r, c] of candidates[idx]) {
            const key = `${r},${c}`;
            if (usedCells.has(key)) continue;
            if (!canPlace(r, c)) continue;

            placed.push([r, c]);
            usedCells.add(key);
            backtrack(idx + 1);
            placed.pop();
            usedCells.delete(key);
        }
    }

    backtrack(0);
    return solutionCount === 1;
}

// Full level generation
function generateLevel(size, pandaCount) {
    for (let attempt = 0; attempt < 500; attempt++) {
